class _FocusRing extends StatelessWidget {
  const _FocusRing({required this.size, required this.timeSize});

  final double size;
  final double timeSize;

  @override
  Widget build(BuildContext context) {
    // Fixed-size art in a width-flexible slot: when the slot is narrower
    // than [size], scale the ring down uniformly instead of overflowing
    // the card (issue #1824, the 7.3px right overflow on page 1).
    return FittedBox(
      fit: BoxFit.scaleDown,
      child: SizedBox(
        width: size,
        height: size,
        child: Stack(
          alignment: Alignment.center,
          children: [
            SizedBox(
              width: size,
              height: size,
              child: CircularProgressIndicator(
                value: 0.75,
                strokeWidth: size * 0.05,
